// Site admin: delete | pause | resume | cadence (pages_per_week 0-3) | unpublish (keyword) | monitors (AI visibility / backlinks / monthly audit settings)
// | prospect (prospect_domain + status contacted / won / rejected / ignored / new, note, contact_email) | ai_prompts (add custom questions, switch some off) — by site_id or domain.
// The table-ensure nodes before this one output table objects, so the request is read from the trigger (live finding 2026-10-02).
let t = {}; try { t = (($('Admin Run').first() || {}).json) || {}; } catch (e) { t = ($input.first() || {}).json || {}; }
if (t.body && typeof t.body === 'object') t = { ...t, ...t.body };
const action = String(t.action || '').toLowerCase();
const normD = (x) => String(x || '').toLowerCase().trim().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/[\/?#].*$/, '');
const domain = normD(t.domain) || String(t.site_id || '').replace(/^site_/, '').replace(/-/g, '.');
const site_id = String(t.site_id || '').trim() || (normD(t.domain) ? 'site_' + normD(t.domain).replace(/[^a-z0-9]+/g, '-') : '');
if (!['delete', 'pause', 'resume', 'cadence', 'unpublish', 'monitors', 'prospect', 'ai_prompts'].includes(action)) throw new Error('action must be delete, pause, resume, cadence, unpublish, monitors, prospect or ai_prompts');
if (!site_id) throw new Error('site_id or domain is required');
const pages = Math.min(3, Math.max(0, Number(t.pages_per_week == null ? t.blogs_per_week : t.pages_per_week) || 0));
if (action === 'cadence' && t.pages_per_week == null && t.blogs_per_week == null) throw new Error('pages_per_week (0-3) is required for action cadence');
const keyword = String(t.keyword || '').trim().toLowerCase().replace(/\s+/g, ' ');
if (action === 'unpublish' && !keyword) throw new Error('keyword is required for action unpublish');
const prospect_domain = normD(t.prospect_domain);
const pstatus = String(t.status || '').toLowerCase();
if (action === 'prospect' && !prospect_domain) throw new Error('prospect_domain is required for action prospect');
if (action === 'prospect' && pstatus && !['new', 'contacted', 'won', 'rejected', 'ignored'].includes(pstatus)) throw new Error('status must be new, contacted, won, rejected or ignored');
const add_prompts = (Array.isArray(t.add) ? t.add : (Array.isArray(t.prompts) ? t.prompts : [])).map(x => String(typeof x === 'object' ? x.prompt : x).trim()).filter(x => x.length >= 10).slice(0, 15);
const off_prompts = (Array.isArray(t.remove) ? t.remove : []).map(x => String(x).trim()).filter(Boolean);
if (action === 'ai_prompts' && !add_prompts.length && !off_prompts.length) throw new Error('add (questions to track) or remove (prompt ids or texts) is required for action ai_prompts');
const monitors = (t.monitors && typeof t.monitors === 'object') ? t.monitors : (action === 'monitors' ? t : {});
return [{ json: { action, site_id, domain: normD(t.domain) || '', status: action === 'pause' ? 'paused' : 'active', pages_per_week: pages, cadence_status: pages > 0 ? 'active' : 'off', keyword, prospect_domain, prospect_type: String(t.type || '').toLowerCase(), prospect_status: pstatus, contact_email: /^[^@\s]+@[^@\s]+\.[a-z]{2,}$/i.test(String(t.contact_email || '').trim()) ? String(t.contact_email).trim().toLowerCase() : '', note: t.note == null ? null : String(t.note).slice(0, 500), add_prompts, off_prompts, monitors, updated_at: new Date().toISOString(), request_id: String(t.request_id || '') } }];

// Site Admin "monitors": merges the given settings over the stored seo_monitors row (exact columns). Settings: ai_visibility, ai_engines
// (chatgpt, perplexity, gemini, claude, ai_overview, ai_mode), ai_prompts_max (3-50), ai_pulse (daily AI Pulse, v4.9), backlinks, audit_monthly, audit_pages (50-1000), audit_js,
// competitors (domains), brand_names.
const a = $('Admin Action').first().json; const m = a.monitors || {};
let old = {}; try { old = $('Load Monitors (Admin)').all().map(i => i.json).find(x => x && x.site_id === a.site_id) || {}; } catch (e) {}
const has = (k) => m[k] !== undefined && m[k] !== null && m[k] !== '';
const b = (k, dflt) => has(k) ? !/^(false|0|no|off)$/i.test(String(m[k])) : (old[k] === undefined || old[k] === null || old[k] === '' ? dflt : !(old[k] === false || old[k] === 'false'));
const list = (v) => (Array.isArray(v) ? v : String(v || '').split(/[\n,;]+/)).map(x => String(x).trim()).filter(Boolean);
const normD = (x) => String(x || '').toLowerCase().trim().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/[\/?#].*$/, '');
const ENG = ['chatgpt', 'perplexity', 'gemini', 'claude', 'ai_overview', 'ai_mode'];
const __row = { site_id: a.site_id, domain: a.domain || old.domain || '', ai_visibility: b('ai_visibility', true), ai_engines: has('ai_engines') ? list(m.ai_engines).map(e => e.toLowerCase()).filter(e => ENG.includes(e)).join(', ') : String(old.ai_engines || ''),
  ai_prompts_max: has('ai_prompts_max') ? Math.min(50, Math.max(3, parseInt(m.ai_prompts_max, 10) || 20)) : (Number(old.ai_prompts_max) || 20), ai_pulse: b('ai_pulse', true), backlinks: b('backlinks', true), audit_monthly: b('audit_monthly', true),
  audit_pages: has('audit_pages') ? Math.min(1000, Math.max(50, parseInt(m.audit_pages, 10) || 200)) : (Number(old.audit_pages) || 200), audit_js: b('audit_js', false),
  competitors: has('competitors') ? list(m.competitors).map(normD).filter(Boolean).slice(0, 5).join(', ') : String(old.competitors || ''), brand_names: has('brand_names') ? list(m.brand_names).join(', ') : String(old.brand_names || ''),
  updated_at: a.updated_at, request_id: a.request_id || '' };
if (__row.audit_js && __row.audit_pages > 500) __row.audit_pages = 500;   // JavaScript rendering is limited to 500 pages per audit
return [{ json: __row }];

// Site Admin "prospect": sets the status (and note) of a link prospect for the site — every type of that domain unless `type` is given.
// Rows keep all other fields (exact seo_link_prospects columns). Status won also stamps won_at; contacted stamps contacted_at (v4.10: the
// Backlink Monitor drafts follow-up 1 after 7 days and follow-up 2 after 14 days without a reply).
const a = $('Admin Action').first().json;
let rows = []; try { rows = $('Load Link Prospects (Admin)').all().map(i => i.json).filter(x => x && x.site_id === a.site_id && x.prospect_domain === a.prospect_domain && (!a.prospect_type || x.type === a.prospect_type)); } catch (e) {}
const COLS = ['site_id', 'domain', 'prospect_domain', 'type', 'rank', 'spam_score', 'detail', 'source_url', 'target_url', 'status', 'first_seen', 'last_seen', 'won_at', 'outreach_subject', 'outreach_body', 'note',
  'score', 'origin', 'contact_email', 'contact_url', 'contacted_at', 'followup_step', 'followup_subject', 'followup_body', 'verified_at'];
const NUM = ['rank', 'spam_score', 'score', 'followup_step'];
if (!rows.length) rows = [{ site_id: a.site_id, domain: a.domain, prospect_domain: a.prospect_domain, type: a.prospect_type || 'manual', rank: 0, spam_score: 0, detail: 'added by hand', source_url: '', target_url: '', status: 'new', first_seen: a.updated_at, last_seen: a.updated_at, won_at: '', outreach_subject: '', outreach_body: '', note: '', score: 0, origin: 'manual', contact_email: '', contact_url: '', contacted_at: '', followup_step: 0, followup_subject: '', followup_body: '', verified_at: '' }];
return rows.map(r => { const o = {}; for (const c of COLS) o[c] = r[c] == null ? (NUM.includes(c) ? 0 : '') : r[c];
  if (a.prospect_status) { o.status = a.prospect_status; if (a.prospect_status === 'won' && !o.won_at) o.won_at = a.updated_at;
    if (a.prospect_status === 'contacted' && r.status !== 'contacted') { o.contacted_at = a.updated_at; o.followup_step = 0; o.followup_subject = ''; o.followup_body = ''; } }
  if (a.contact_email) o.contact_email = a.contact_email;
  if (a.note !== null && a.note !== undefined) o.note = a.note; return { json: o }; });

// Site Admin "ai_prompts": adds custom buyer questions (source custom, tracked weekly before the automatic ones) and switches questions off
// (by prompt id or exact text). Exact seo_ai_prompts columns (v4.9: stage, cluster, volume, origin, updated_at); upsert by prompt_id.
const a = $('Admin Action').first().json;
let rows = []; try { rows = $('Load AI Prompts (Admin)').all().map(i => i.json).filter(x => x && x.site_id === a.site_id); } catch (e) {}
const hash = (t) => { let h = 5381; for (const c of String(t)) h = ((h * 33) ^ c.charCodeAt(0)) >>> 0; return h.toString(36); };
const norm = (t) => String(t || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const out = [];
for (const q of a.add_prompts) { const id = 'p_' + hash(a.site_id + '|' + norm(q)); const old = rows.find(r => r.prompt_id === id);
  out.push({ prompt_id: id, site_id: a.site_id, domain: a.domain || (old || {}).domain || '', prompt: q, kind: 'custom', topic: (old || {}).topic || '', keyword: (old || {}).keyword || norm(q).split(' ').slice(0, 5).join(' '), source: 'custom', status: 'active', created_at: (old || {}).created_at || a.updated_at,
    stage: (old || {}).stage || 'consideration', cluster: (old || {}).cluster || '', volume: (old || {}).volume === undefined || (old || {}).volume === '' ? null : (old || {}).volume, origin: 'custom', updated_at: a.updated_at }); }
for (const x of a.off_prompts) for (const r of rows.filter(r => r.prompt_id === x || norm(r.prompt) === norm(x))) out.push({ prompt_id: r.prompt_id, site_id: r.site_id, domain: r.domain, prompt: r.prompt, kind: r.kind, topic: r.topic, keyword: r.keyword, source: r.source, status: 'off', created_at: r.created_at,
  stage: r.stage || '', cluster: r.cluster || '', volume: r.volume === undefined || r.volume === '' ? null : r.volume, origin: r.origin || '', updated_at: a.updated_at });
return out.length ? out.map(r => ({ json: r })) : [{ json: { skip: true } }];

// seo_cadence row for the admin action "cadence" (upserted by site_id).
const a = $('Admin Action').first().json;
return [{ json: { site_id: a.site_id, domain: a.domain, pages_per_week: a.pages_per_week, status: a.cadence_status, updated_at: a.updated_at, request_id: a.request_id } }];

// Rows affected by the admin action (0 = no site / row with that id or keyword).
const a = $('Admin Action').first().json; const rows = $input.all().map(i => i.json).filter(r => r && typeof r === 'object');
const err = rows.find(r => r.error);
return [{ json: { ...a, affected: rows.filter(r => r.site_id || r.ladder_id).length, error: err ? String((err.error.message || err.error.description || err.error)).slice(0, 200) : null } }];
